import { Component, EventEmitter, Output } from '@angular/core';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-register-dialog',
  templateUrl: './register-dialog.component.html',
  styleUrls: ['./register-dialog.component.css']
})
export class RegisterDialogComponent {
  @Output() close = new EventEmitter<void>();
  @Output() registerSuccess = new EventEmitter<void>();
  @Output() switchToLogin = new EventEmitter<void>();

  name = '';
  email = '';
  password = '';
  confirmPassword = '';
  submitting = false;
  error: string | null = null;

  constructor(private authService: AuthService) {}

  onSubmit() {
    // Validierung
    if (!this.name || !this.email || !this.password || !this.confirmPassword) {
      this.error = 'Bitte fülle alle Felder aus.';
      return;
    }

    if (this.password !== this.confirmPassword) {
      this.error = 'Passwörter stimmen nicht überein.';
      return;
    }

    if (this.password.length < 6) {
      this.error = 'Passwort muss mindestens 6 Zeichen lang sein.';
      return;
    }

    this.submitting = true;
    this.error = null;

    this.authService.register(this.name, this.email, this.password).subscribe({
      next: (response) => {
        if (response.success) {
          this.registerSuccess.emit();
        } else {
          this.error = response.message;
        }
        this.submitting = false;
      },
      error: (error) => {
        console.error('Registrierungs-Fehler:', error);
        this.error = error.error?.message || 'Registrierung fehlgeschlagen. Bitte versuche es erneut.';
        this.submitting = false;
      }
    });
  }

  onClose() {
    this.close.emit();
  }

  onSwitchToLogin() {
    this.switchToLogin.emit();
  }

  onBackdropClick(event: MouseEvent) {
    if (event.target === event.currentTarget) {
      this.onClose();
    }
  }
}
<div class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50" (click)="onBackdropClick($event)">
  <div class="bg-white rounded-lg shadow-xl w-full max-w-md mx-4 p-8">
    <!-- Header -->
    <div class="flex justify-between items-center mb-6">
      <h2 class="text-2xl text-gray-900">Registrieren</h2>
      <button 
        (click)="onClose()"
        class="text-gray-400 hover:text-gray-600">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
        </svg>
      </button>
    </div>

    <!-- Error Message -->
    <div *ngIf="error" class="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg">
      <p class="text-sm text-red-800">{{ error }}</p>
    </div>

    <!-- Form -->
    <form (ngSubmit)="onSubmit()">
      <div class="mb-4">
        <label class="block text-sm text-gray-700 mb-2">Name</label>
        <input
          type="text"
          [(ngModel)]="name"
          name="name"
          required
          placeholder="Dein Name"
          class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent">
      </div>

      <div class="mb-4">
        <label class="block text-sm text-gray-700 mb-2">E-Mail</label>
        <input
          type="email"
          [(ngModel)]="email"
          name="email"
          required
          placeholder="deine@email.com"
          class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent">
      </div>

      <div class="mb-4">
        <label class="block text-sm text-gray-700 mb-2">Passwort</label>
        <input
          type="password"
          [(ngModel)]="password"
          name="password"
          required
          placeholder="Mindestens 6 Zeichen"
          class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent">
      </div>

      <div class="mb-6">
        <label class="block text-sm text-gray-700 mb-2">Passwort wiederholen</label>
        <input
          type="password"
          [(ngModel)]="confirmPassword"
          name="confirmPassword"
          required
          placeholder="••••••••"
          class="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent">
      </div>

      <button
        type="submit"
        [disabled]="submitting"
        class="w-full px-6 py-3 bg-orange-600 text-white rounded-lg hover:bg-orange-700 disabled:bg-gray-300 disabled:cursor-not-allowed transition-colors mb-4">
        {{ submitting ? 'Wird registriert...' : 'Registrieren' }}
      </button>

      <p class="text-center text-sm text-gray-600">
        Bereits ein Konto?
        <button
          type="button"
          (click)="onSwitchToLogin()"
          class="text-orange-600 hover:text-orange-700 ml-1">
          Jetzt anmelden
        </button>
      </p>
    </form>
  </div>
</div>
